## Submitted testbench
```systemverilog
module tb;
  // -------------------------------------------------
  //  Top‑level testbench for the AXI‑Stream UART
  // -------------------------------------------------
  //  All signals are connected only through the DUT ports.
  //  The design is exercised until the coverage point
  //  R29_accept_during_frame_error is hit, then $finish()
  //  is called.
  // -------------------------------------------------

  // -------------------------------------------------
  //  Clock and reset
  // -------------------------------------------------
  localparam int CLK_PERIOD = 8;                 // 125 MHz
  logic clk        = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  //  DUT ports (default parameters)
  // -------------------------------------------------
  logic        rst;
  logic [15:0] prescale;
  logic        rxd;
  logic        s_axis_tvalid;
  logic [7:0]  s_axis_tdata;

  //  AXI‑Stream output of the RX side
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;   // driven by the testbench

  //  Additional status ports (unused)
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // -------------------------------------------------
  //  Connect the DUT
  // -------------------------------------------------
  logic unused_s_axis_tready;   // DUT output – left un‑driven
  assign unused_s_axis_tready = 1'b0;

  uart #(.DATA_WIDTH(8)) dut (
    .clk                (clk),
    .rst                (rst),
    .s_axis_tdata       (s_axis_tdata),
    .s_axis_tvalid      (s_axis_tvalid),
    .s_axis_tready      (unused_s_axis_tready), // output, not driven
    .m_axis_tdata       (m_axis_tdata),
    .m_axis_tvalid      (m_axis_tvalid),
    .m_axis_tready      (m_axis_tready),        // input – driven by TB
    .rxd                (rxd),
    .txd                (),
    .tx_busy            (),
    .rx_busy            (),
    .rx_overrun_error   (),
    .rx_frame_error     (rx_frame_error),
    .prescale           (prescale)
  );

  // -------------------------------------------------
  //  Simple clock generation
  // -------------------------------------------------
  initial clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // -------------------------------------------------
  //  Reset sequence
  // -------------------------------------------------
  initial begin
    rst          = 1'b1;
    prescale     = 16'd5;
    rxd          = 1'b1;
    s_axis_tdata   = 8'h00;
    s_axis_tvalid  = 1'b0;
    m_axis_tready  = 1'b0;
    # (CLK_PERIOD*20);
    rst          = 1'b0;
  end

  // -------------------------------------------------
  //  Helpers
  // -------------------------------------------------
  task automatic wait_cycles(input int n);
    repeat (n) @(posedge clk);
  endtask

  // Drive rxd for a given number of clock cycles
  task automatic drive_rxd(input logic level, input int cycles);
    rxd <= level;
    wait_cycles(cycles);
  endtask

  // Send one UART byte (LSB‑first) – optional stop bit
  task automatic uart_send_byte(input logic [7:0] data, input logic stop_high);
    // start bit
    drive_rxd(1'b0, 40);
    // data bits
    for (int i = 0; i < 8; i++) begin
      drive_rxd(data[i], 40);
    end
    // stop bit
    drive_rxd(stop_high ? 1'b1 : 1'b0, 40);
  endtask

  // -------------------------------------------------
  //  Coverage‑point monitor
  // -------------------------------------------------
  always @(posedge clk) begin
    if (!rst &&
        !$past(rst) &&
        $past(rx_frame_error) &&
        $past(m_axis_tvalid) &&
        $past(m_axis_tready) &&
        ($past(m_axis_tdata) == 8'h3C) &&
        !m_axis_tvalid &&
        (m_axis_tdata == 8'h3C)) begin
      $finish;
    end
  end

  // -------------------------------------------------
  //  Main stimulus
  // -------------------------------------------------
  initial begin
    // -----------------------------------------------------------------
    //  1) Wait for reset de‑assertion
    // -----------------------------------------------------------------
    @(negedge rst);
    #100;

    // -----------------------------------------------------------------
    //  2) Force a frame‑error by sending a malformed frame
    //     (start‑bit, 8 data bits, stop‑bit low).
    // -----------------------------------------------------------------
    uart_send_byte(8'h00, 1'b0);   // stop bit low → frame_error asserted

    // Allow a few cycles for the error to be latched
    repeat (5) @(posedge clk);

    // -----------------------------------------------------------------
    //  3) Now send the word 0x3C with a proper stop bit.
    //     While the word is being received we keep m_axis_tready high
    //     so the Rx accepts it immediately.
    // -----------------------------------------------------------------
    m_axis_tready = 1'b1;                 // always ready
    uart_send_byte(8'h3C, 1'b1);           // data = 0x3C, stop‑bit high

    // Wait until the coverage condition can be evaluated
    repeat (30) @(posedge clk);

    // -----------------------------------------------------------------
    //  4) End of simulation – $finish is called automatically
    // -----------------------------------------------------------------
    $finish;
  end

endmodule
